<dialog id="theme-settings"><form method="post" enctype="multipart/form-data" action="{{ route('presentations.theme',$presentation) }}">@csrf @method('PUT')<h2>Tema de la presentación</h2><p>Se aplica a todas las diapositivas y también al editor visual.</p><label>Tema<select name="theme" required><option value="koqoi" @selected($presentation->theme==='koqoi' || !$presentation->theme)>Koqoi · aros</option><option value="minimal" @selected($presentation->theme==='minimal')>Minimalista</option><option value="ocean" @selected($presentation->theme==='ocean')>Océano</option><option value="sunset" @selected($presentation->theme==='sunset')>Atardecer</option><option value="forest" @selected($presentation->theme==='forest')>Bosque</option><option value="night" @selected($presentation->theme==='night')>Noche</option><option value="custom" @selected($presentation->theme==='custom')>Personalizado</option></select></label><div class="theme-colors"><label>Fondo<input type="color" name="background_color" value="{{ data_get($presentation->theme_settings,'background_color','#fffdf8') }}"></label><label>Títulos<input type="color" name="title_color" value="{{ data_get($presentation->theme_settings,'title_color','#102a2e') }}"></label><label>Texto<input type="color" name="body_color" value="{{ data_get($presentation->theme_settings,'body_color','#536568') }}"></label><label>Acento<input type="color" name="accent_color" value="{{ data_get($presentation->theme_settings,'accent_color','#ff6846') }}"></label></div><label>Decoración<select name="decoration"><option value="circle" @selected(data_get($presentation->theme_settings,'decoration','circle')==='circle')>Aros</option><option value="none" @selected(data_get($presentation->theme_settings,'decoration')==='none')>Sin decoración</option></select></label><label>Fondo personalizado<input type="file" name="background_image" accept="image/jpeg,image/png,image/webp"></label>@if(data_get($presentation->theme_settings,'background_path'))<label>