<style>.classic-elements{position:absolute!important;inset:0;z-index:3!important;max-width:none!important;margin:0!important;pointer-events:none}.classic-object{position:absolute;white-space:pre-wrap;overflow:hidden;transform-origin:center;line-height:1.15}.classic-object.object-image{object-fit:cover}.theme-colors{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.theme-colors input{height:42px;padding:3px}@media(max-width:700px){.theme-colors{grid-template-columns:1fr 1fr}}</style>
<script>
(()=>{const csrf=document.querySelector('meta[name="csrf-token"]').content,sorter=document.querySelector('#slide-sorter'),status=document.querySelector('#order-status'),backgrounds=@json($presentation->slides->mapWithKeys(fn($slide)=>[$slide->id=>$slide->background_path ? asset('storage/'.$slide->background_path) : null])),designs=@json($presentation->slides->mapWithKeys(fn($slide)=>[$slide->id=>$slide->design ?? []]));
const saveOrder=async()=>{const ids=[...sorter.children].map(item=>Number(item.dataset.slideId)),stack=document.querySelector('.slide-stack');ids.forEach((id,index)=>{const panel=document.getElementById(`slide-${id}`);stack.append(panel);panel.querySelector('.slide-number').textContent=`DIAPOSITIVA ${index+1}`;panel.querySelector('.editor-canvas>span').textContent=String(index+1).padStart(2,'0')});status.textContent='Guardando orden…';const response=await fetch('{{ route('slides.reorder',$presentation) }}',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({slide_ids:ids})});if(!response.ok){status.textContent='No se pudo guardar';return}status.textContent='Orden guardado';[...sorter.children].forEach((item,index)=>item.querySelector('b').textContent=index+1)};
let dragged=null;sorter.addEventListener('dragstart',event=>{dragged=event.target.closest('.slide-sort-item');dragged?.classList.add('dragging')});sorter.addEventListener('dragend',()=>{dragged?.classList.remove('dragging');dragged=null});sorter.addEventListener('dragover',event=>{event.preventDefault();const target=event.target.closest('.slide-sort-item');if(target&&dragged&&target!==dragged){const box=target.getBoundingClientRect();sorter.insertBefore(dragged,event.clientY<box.top+box.height/2?target:target.nextSibling)}});sorter.addEventListener('drop',event=>{event.preventDefault();saveOrder()});sorter.addEventListener('click',event=>{const button=event.target.closest('.move-slide');if(!button)return;const item=button.closest('.slide-sort-item'),direction=Number(button.dataset.direction),sibling=direction<0?item.previousElementSibling:item.nextElementSibling;if(!sibling)return;direction<0?sorter.insertBefore(item,sibling):sorter.insertBefore(sibling,item);saveOrder()});
document.querySelectorAll('.slide-editor').forEach((editor,index)=>{const id=Number(editor.id.replace('slide-','')),form=editor.querySelector('.slide-content-form'),design=designs[id]||{},title=form.querySelector('[name=title]'),body=form.querySelector('[name=body]'),style=form.querySelector('[name=background_style]'),color=form.querySelector('[name=background_color]'),file=form.querySelector('[name=background_image]'),controls=document.createElement('div'),canvas=document.createElement('div');controls.className='design-controls';controls.innerHTML=`<h4>Diseño personalizado</h4><label>Tipo de fondo<select name="background_mode"><option value="preset">Prediseñado</option><option value="custom">Personalizado</option></select></label><label>Color del título<input type="color" name="title_color" value="${design.title_color||'#102a2e'}"></label><label>Color del texto<input type="color" name="body_color" value="${design.body_color||'#536568'}"></label><label>Color de acento<input type="color" name="accent_color" value="${design.accent_color||'#ff6846'}"></label><label>Fondo de pregunta<input type="color" name="question_background_color" value="${design.question_background_color||'#102a2e'}"></label><label>Texto de pregunta<input type="color" name="question_text_color" value="${design.question_text_color||'#ffffff'}"></label><label>Decoración<select name="decoration"><option value="circle">Círculos</option><option value="none">Sin decoración</option></select></label>`;form.querySelector('.layout-picker').after(controls);controls.querySelector('[name=background_mode]').value=design.background_mode||(backgrounds[id]?'custom':'preset');controls.querySelector('[name=decoration]').value=design.decoration||'circle';const mode=controls.querySelector('[name=background_mode]'),titleColor=controls.querySelector('[name=title_color]'),bodyColor=controls.querySelector('[name=body_color]'),accentColor=controls.querySelector('[name=accent_color]'),decoration=controls.querySelector('[name=decoration]');canvas.className='editor-canvas';canvas.innerHTML=`<span>${String(index+1).padStart(2,'0')}</span><div class="classic-fallback"><h2></h2><p></p></div><div class="classic-elements"></div>`;editor.querySelector('.slide-number').after(canvas);const head=document.createElement('div');head.className='slide-editor-actions';if(sorter.children.length>1)head.innerHTML=`<form method="post" action="/diapositivas/${id}" onsubmit="return confirm('¿Eliminar esta diapositiva y todas sus interacciones?')"><input type="hidden" name="_token" value="${csrf}"><input type="hidden" name="_method" value="DELETE"><button class="delete-slide">Eliminar diapositiva</button></form>`;editor.prepend(head);const paint=()=>{canvas.className=`editor-canvas background-${style.value} mode-${mode.value} decor-${decoration.value}`;canvas.style.setProperty('--slide-color',color.value);canvas.style.setProperty('--title-color',titleColor.value);canvas.style.setProperty('--body-color',bodyColor.value);canvas.style.setProperty('--accent-color',accentColor.value);if(backgrounds[id]){canvas.classList.add('has-background-image');canvas.style.setProperty('--slide-image',`url('${backgrounds[id]}')`)}const elements=design.elements||[],layer=canvas.querySelector('.classic-elements'),fallback=canvas.querySelector('.classic-fallback');fallback.hidden=elements.length>0;layer.replaceChildren();elements.forEach(source=>{const item={...source};if(item.id===`legacy-title-${id}`){item.text=title.value;item.fill=titleColor.value}if(item.id===`legacy-body-${id}`){item.text=body.value;item.fill=bodyColor.value}const el=item.type==='image'?document.createElement('img'):document.createElement('div');el.className=`classic-object object-${item.type}`;if(item.type==='image')el.src=item.src;else if(item.type==='text')el.textContent=item.text||'';el.style.cssText=`left:${item.x/12.8}%;top:${item.y/7.2}%;width:${item.width/12.8}%;height:${item.height/7.2}%;transform:rotate(${item.rotation||0}deg);color:${item.fill||'#102a2e'};background:${item.type==='rect'?(item.fill||'#ff6846'):'transparent'};font-size:${(item.fontSize||30)/12.8}vw;font-family:${item.fontFamily||'Arial'};font-weight:${item.fontStyle==='bold'?'700':'400'}`;layer.append(el)});canvas.querySelector('h2').textContent=title.value||'Sin título';canvas.querySelector('p').textContent=body.value||'Escribe contenido para ver cómo quedará.'};[title,body,style,color,mode,titleColor,bodyColor,accentColor,decoration].forEach(input=>input.addEventListener('input',paint));file.addEventListener('change',()=>{const selected=file.files[0];if(!selected)return;const reader=new FileReader;reader.onload=()=>{backgrounds[id]=reader.result;mode.value='custom';paint()};reader.readAsDataURL(selected)});paint()});
document.querySelectorAll('.activity').forEach(activity=>{const dialog=activity.nextElementSibling;if(!dialog?.id.startsWith('edit-activity-'))return;const id=dialog.id.replace('edit-activity-',''),actions=document.createElement('div');actions.className='activity-actions';const edit=activity.querySelector('.edit-activity');edit.replaceWith(actions);actions.append(edit);actions.insertAdjacentHTML('beforeend',`<form method="post" action="/actividades/${id}" onsubmit="return confirm('¿Eliminar esta interacción y sus respuestas?')"><input type="hidden" name="_token" value="${csrf}"><input type="hidden" name="_method" value="DELETE"><button class="delete-activity">Eliminar</button></form>`)});
document.querySelectorAll('[data-counter]').forEach(el=>{const out=document.getElementById(el.dataset.counter),update=()=>out.textContent=`${el.value.length}/${el.maxLength}`;el.addEventListener('input',update)})})();
</script>
</x-layouts.app>
